import React from 'react';

export default function Sidebar({ setCurrentPage, currentPage }) {
  const menuItems = [
    { name: 'Dashboard', icon: '📊' },
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
  ];

  return (
    <div style={{ 
      width: '240px', 
      backgroundColor: '#0f172a', 
      color: '#ffffff', 
      padding: '20px 10px',
      boxShadow: '2px 0 5px rgba(0,0,0,0.05)',
      display: 'flex',
      flexDirection: 'column',
      gap: '5px'
    }}>
      {menuItems.map((item, i) => {
        const isActive = currentPage === item.name || (currentPage === 'Classes' && item.name === 'Teachers & Classes');
        
        return (
          <div 
            key={i} 
            onClick={() => {
              if (item.name === 'Teachers & Classes') {
                setCurrentPage('Classes');
              } else {
                setCurrentPage(item.name);
              }
            }}
            style={{ 
              padding: '12px 15px', 
              borderRadius: '6px',
              cursor: 'pointer', 
              display: 'flex', 
              alignItems: 'center', 
              gap: '12px',
              transition: 'all 0.2s ease',
              backgroundColor: isActive ? '#16a34a' : 'transparent',
              fontWeight: isActive ? '600' : '400'
            }}
            onMouseEnter={(e) => {
              if(!isActive) e.currentTarget.style.backgroundColor = '#1e293b';
            }}
            onMouseLeave={(e) => {
              if(!isActive) e.currentTarget.style.backgroundColor = 'transparent';
            }}
          >
            <span>{item.icon}</span> 
            <span style={{ fontSize: '14px' }}>{item.name}</span>
          </div>
        );
      })}
    </div>
  );
}
